`InterleavedFx3` pixel buffer:

```
   let src = vImage.PixelBuffer<vImage.InterleavedFx3>(
       pixelValues: [0.25, 0.5, 0.75] as [Float],
       size: vImage.Size(width: 1, height: 1))

   let dest = vImage.PixelBuffer<vImage.PlanarFx3>(interleavedBuffer: src)

   // Prints "[0.25] [0.5] [0.75]"
   dest.withUnsafePixelBuffers { pixelBuffers in
       for pixelBuffer in pixelBuffers {
           print(pixelBuffer.array)
       }
   }
```

Initializes a `PlanarFx4` pixel buffer from an `InterleavedFx4` pixel buffer.

Use this function to deinterleave a pixel buffer and store the result as homogeneous planes
that are represented by multiple underlying vImage buffers.

For example, the following code creates a new `PlanarFx4` pixel buffer from an
`InterleavedFx4` pixel buffer:

```
   let src = vImage.PixelBuffer<vImage.InterleavedFx4>(
       pixelValues: [0.2, 0.4, 0.6, 0.8] as [Float],
       size: vImage.Size(width: 1, height: 1))

   let dest = vImage.PixelBuffer<vImage.PlanarFx4>(interleavedBuffer: src)

   // Prints "[0.2] [0.4] [0.6] [0.8]"
   dest.withUnsafePixelBuffers { pixelBuffers in
       for pixelBuffer in pixelBuffers {
           print(pixelBuffer.array)
       }
   }
```

Adds a tensor-tensor select operation to the current graph.

- Parameter valueIfTrue: The values that the operation returns when the corresponding value in `self` is `true`.
- Parameter valueIfFalse: The values that the operation returns when the corresponding value in `self` is `false`.

For example, the following code returns the `valueIfTrue` elements when the corresponding elements in `z` are `true`
and the elements in `valueIfFalse` when the corresponding elements in `z` are `false`:
   ```
   let ctx = try BNNSGraph.makeContext {

       builder in

       let z = builder.argument(dataType: Bool.self, shape: [8])

       let x = builder.argument(dataType: Float.self, shape: [8])
       let y = builder.argument(dataType: Float.self, shape: [8])

       let masked = z.select(x, y)

       return [ masked ]
   }

   let z = BNNSTensor.allocate(initializingFrom: [true, true, false, false,
                                                  true, true, false, false],
                               shape: [8], stride: [1])

   let x = BNNSTensor.allocate(initializingFrom: [1, 2, 3, 4, 5, 6, 7, 8] as [Float],
                               shape: [8], stride: [1])
   let y = BNNSTensor.allocate(initializingFrom: [10, 20, 30, 40, 50, 60, 70, 80] as [Float],
                               shape: [8], stride: [1])

   let tensor_tensor = BNNSTensor.allocateUninitialized(scalarType: Float.self, shape: [8], stride: [1])

   var args = [tensor_tensor, tensor_scalar, scalar_tensor, z, x, y]

   try ctx.executeFunction(arguments: &args)

   // Prints "[1.0, 2.0, 30.0, 40.0, 5.0, 6.0, 70.0, 80.0]".
   print(tensor_tensor.makeArray(of: Float.self))

   ```
